87	/** Hash FNV-1a 32-bit determinístico — pra idempotency_key. */
88	function fnv1aHash(s: string): string {
89	  let h = 2166136261;
90	  for (let i = 0; i < s.length; i++) {
91	    h ^= s.charCodeAt(i);
92	    h = Math.imul(h, 16777619);
93	  }
94	  return (h >>> 0).toString(36);
95	}
