1	/**
2	 * @module types/drp
3	 *
4	 * Tipos do módulo DRP (Distribution Requirements Planning) — Plano de Reposição.
5	 *
6	 * O DRP calcula sugestões de envio fábrica → lojas com base em demanda
7	 * histórica DoW-aware (dia da semana), estoque atual e em-trânsito.
8	 *
9	 * Algoritmo: forecast = Σ µ_dow_loja_produto sobre dias do horizonte;
10	 * SS = Z × √Σσ²; sugestão = max(0, forecast + SS - estoque - em_trânsito).
11	 *
12	 * Restrição dura: shelf-life uniforme 5d — bloqueia se horizonte excede 5d.
13	 */
14	
15	/** Identificador de loja (loja_id em produtos_master, estoque, etc.). */
16	export type LojaId = 1 | 2 | 3 | 4 | 5 | 6;
17	
18	/** Lookback histórico em dias (ou 'all' = vida toda). */
19	export type DrpLookback = 30 | 60 | 90 | 180 | 'all';
20	
21	/** Z-score do service level (1.28=90%, 1.65=95%, 1.96=97.5%, 2.33=99%). */
22	export type DrpServiceLevelZ = 1.28 | 1.65 | 1.96 | 2.33;
23	
24	/** Map Z-score → label legível. */
25	export const SERVICE_LEVEL_LABELS: Record<DrpServiceLevelZ, string> = {
26	  1.28: '90%',
27	  1.65: '95%',
28	  1.96: '97.5%',
29	  2.33: '99%',
30	};
31	
32	/** Constante de shelf-life uniforme em dias (Momma é doces frescos, 5d max). */
33	export const SHELF_LIFE_DAYS = 5;
34	
35	/** Status visual de uma loja na timeline do DRP. */
36	export type DrpLojaStatus = 'pendente' | 'em_construcao' | 'concluida';
37	
38	/** Parâmetros globais do plano (afetam todas as lojas). */
39	export interface DrpParams {
40	  /** Data em que o estoque chegará nas lojas (ISO YYYY-MM-DD). */
41	  data_chegada: string;
42	  /** Data inclusive até quando o estoque deve durar (ISO YYYY-MM-DD). */
43	  data_durar_ate: string;
44	  /** Período de histórico para calcular µ_dow. */
45	  lookback_days: DrpLookback;
46	  /** Z-score do service level. */
47	  service_level_z: DrpServiceLevelZ;
48	}
49	
50	/** Linha calculada de um produto numa loja específica. */
51	export interface DrpRow {
52	  produto_master_id: number;
53	  nome: string;
54	  setor: string;
55	  /** Média de vendas para os DoWs do horizonte (já ponderada). */
56	  mu_dow: number | null;
57	  /** Desvio padrão das vendas DoW. */
58	  sigma_dow: number;
59	  /** Forecast total no horizonte (Σ µ_dow por dia). */
60	  forecast_horizonte: number;
61	  /** Safety stock (Z × √Σσ²). */
62	  safety_stock: number;
63	  /** Estoque atual da loja. */
64	  estoque_loja: number;
65	  /** Em-trânsito (requisições não-finalizadas com expedicao_id). */
66	  em_transito: number;
67	  /** Sugestão calculada (max(0, forecast + SS − estoque − em_transito)). */
68	  sugestao_calculada: number;
69	  /** Sugestão final (calculada ou override manual do operador). */
70	  sugestao_final: number;
71	  /** True se operador sobrescreveu manualmente. */
72	  override_manual: boolean;
73	  /** Cobertura pós-envio em dias (DoW-aware cumulativa). */
74	  doc_pos_envio: number;
75	  /** Data prevista de stockout (null se não esgota no horizonte). */
76	  dia_stockout: string | null;
77	  /** True se tem histórico de vendas; false → linha "sem histórico". */
78	  tem_historico: boolean;
79	}
