158	/** Z-score → service level percentage label. */
159	export function formatServiceLevel(z: DrpServiceLevelZ): string {
160	  return SERVICE_LEVEL_LABELS[z] ?? `${z}σ`;
161	}
162	
163	/** Computa número de dias inclusive entre data_chegada e data_durar_ate. */
164	export function diasHorizonte(params: Pick<DrpParams, 'data_chegada' | 'data_durar_ate'>): number {
165	  const a = new Date(`${params.data_chegada}T00:00:00`);
166	  const b = new Date(`${params.data_durar_ate}T00:00:00`);
167	  const diff = Math.round((b.getTime() - a.getTime()) / 86_400_000);
168	  return Math.max(1, diff + 1); // inclusive nos dois extremos
169	}
170	
171	/** Lista de DoWs (0=domingo) cobertos pelo horizonte. */
172	export function dowsHorizonte(params: Pick<DrpParams, 'data_chegada' | 'data_durar_ate'>): number[] {
173	  const result: number[] = [];
174	  const start = new Date(`${params.data_chegada}T00:00:00`);
175	  const dias = diasHorizonte(params);
176	  for (let i = 0; i < dias; i++) {
177	    const d = new Date(start);
178	    d.setDate(d.getDate() + i);
179	    result.push(d.getDay());
180	  }
181	  return result;
182	}
183	
184	/** Formata ISO YYYY-MM-DD em dd/mm/yyyy (formato BR). */
185	export function formatBrDate(iso: string | null | undefined): string {
186	  if (!iso) return '—';
187	  const [y, m, d] = iso.split('T')[0].split('-');
188	  if (!y || !m || !d) return iso;
189	  return `${d}/${m}/${y}`;
190	}
