77	/** Pagina queries grandes do Supabase (limite default = 1000). */
78	async function fetchAll<T>(query: any): Promise<T[]> {
79	  const PAGE_SIZE = 1000;
80	  let all: T[] = [];
81	  let offset = 0;
82	  while (true) {
83	    const { data, error } = await query.range(offset, offset + PAGE_SIZE - 1);
84	    if (error) throw error;
85	    if (!data || data.length === 0) break;
86	    all = all.concat(data);
87	    if (data.length < PAGE_SIZE) break;
88	    offset += PAGE_SIZE;
89	  }
90	  return all;
91	}
